messages.content:
Tool response:
Tool: find_hazy_ipa_batches
Description: Find Hazy Ipa Batches
Parameters:
    {
      "type": "object",
      "properties": {
        "recipe_name": {
          "type": "string",
          "description": "Name of the recipe to filter by (e.g., 'Hazy IPA')",
          "title": "Recipe Name"
        },
        "start_date": {
          "type": "string",
          "format": "date",
          "description": "Start date for brew date range filter (YYYY-MM-DD)",
          "title": "Start Date"
        },
        "end_date": {
          "type": "string",
          "format": "date",
          "description": "End date for brew date range filter (YYYY-MM-DD)",
          "title": "End Date"
        },
        "hop_lot_number": {
          "type": "string",
          "description": "Lot number of hops used (e.g., 'CIT-2024-01')",
          "title": "Hop Lot Number"
        },
        "min_final_gravity": {
          "type": "number",
          "description": "Minimum final gravity threshold",
          "title": "Min Final Gravity"
        }
      },
      "required": [
        "recipe_name",
        "start_date",
        "end_date",
        "hop_lot_number",
        "min_final_gravity"
      ]
    }
